repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 59), ('omar', 56), ('mia', 25), ('noor', 18), ('omar', 12), ('noor', 45)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.distinct.py:
"""Distinct donor values among donations."""


def new_donors(donations, seen=set()):
    """Return each donor the first time it appears among the donations, in order. donor values already in `seen` are left out."""
    out = []
    for x in donations:
        if x.donor not in seen:
            seen.add(x.donor)
            out.append(x.donor)
    return out


def count_donors(donations):
    """Return how many distinct donor values the donations have."""
    return len(set(x.donor for x in donations))


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)


def largest_pounds(donations):
    """Return the largest pounds, or None when there are no donations."""
    values = [x.pounds for x in donations]
    return max(values) if values else None
